package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string          // PIC X(4) @0 len=4
	TcF      decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Standalone working-storage items
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsC decimal.Decimal = decimal.NewFromInt(0) // PIC S9(3)V99
var WsFreeze int64 = 0 // PIC 99
var WsCount int64 = 0  // PIC 99
var WsFEd string // PIC ZZ9.9 len=5
var WsCEd string // PIC -ZZ9.99 len=7

var curRec TempRec
var inputLines []string
var inputIdx int

func pow10Int64(n int) int64 {
	r := int64(1)
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func formatUnsigned(v decimal.Decimal, intDigits int, decDigits int) string {
	scaled := v.Abs().Shift(int32(decDigits)).Truncate(0).IntPart()
	powDec := pow10Int64(decDigits)
	powInt := pow10Int64(intDigits)
	var intPart int64
	var fracPart int64
	if powDec != 0 {
		intPart = (scaled / powDec) % powInt
		fracPart = scaled % powDec
		if fracPart < 0 {
			fracPart = -fracPart
		}
		if intPart < 0 {
			intPart = -intPart
		}
	} else {
		intPart = scaled % powInt
		if intPart < 0 {
			intPart = -intPart
		}
	}
	var sb strings.Builder
	for i := 0; i < intDigits; i++ {
		div := pow10Int64(intDigits - 1 - i)
		digit := (intPart / div) % 10
		if i < intDigits-1 {
			if intPart < div {
				sb.WriteByte(' ')
			} else {
				sb.WriteByte(byte('0' + digit))
			}
		} else {
			sb.WriteByte(byte('0' + digit))
		}
	}
	if decDigits > 0 {
		sb.WriteByte('.')
		fracStr := fmt.Sprintf("%0*d", decDigits, fracPart)
		sb.WriteString(fracStr)
	}
	return sb.String()
}

func formatSigned(v decimal.Decimal, intDigits int, decDigits int) string {
	sign := ' '
	if v.Sign() < 0 {
		sign = '-'
	}
	return string(sign) + formatUnsigned(v, intDigits, decDigits)
}

func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	if len(line) < 8 {
		line += strings.Repeat(" ", 8-len(line))
	} else if len(line) > 8 {
		line = line[:8]
	}
	curRec.TcSensor = line[0:4]
	fStr := line[4:8]
	var n int64
	for i := 0; i < 4; i++ {
		c := fStr[i]
		if c >= '0' && c <= '9' {
			n = n*10 + int64(c-'0')
		} else {
			n = n * 10
		}
	}
	curRec.TcF = decimal.New(n, -1)
}

func ProcessPara() {
	n := curRec.TcF.Shift(1).Truncate(0).IntPart()
	p := (n - 320) * 50
	var r int64
	if p >= 0 {
		div := p / 9
		rem := p % 9
		if rem*2 >= 9 {
			div++
		}
		r = div
	} else {
		div := p / 9
		rem := p % 9
		if (-rem)*2 >= 9 {
			div--
		}
		r = div
	}
	rMod := r % 100000
	WsC = decimal.New(rMod, -2)
	if WsC.Sign() < 0 {
		WsFreeze = (WsFreeze + 1) % 100
	}
	WsCount = (WsCount + 1) % 100
	WsFEd = formatUnsigned(curRec.TcF, 3, 1)
	WsCEd = formatSigned(WsC, 3, 2)
	line := curRec.TcSensor + " " + WsFEd + "F " + WsCEd + "C"
	fmt.Fprintln(os.Stdout, line)
	ReadPara()
}

func MainPara() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	inputLines = nil
	inputIdx = 0
	start := 0
	for i, b := range data {
		if b == '\n' {
			line := string(data[start:i])
			if len(line) > 0 && line[len(line)-1] == '\r' {
				line = line[:len(line)-1]
			}
			inputLines = append(inputLines, line)
			start = i + 1
		}
	}
	if start < len(data) {
		line := string(data[start:])
		if len(line) > 0 && line[len(line)-1] == '\r' {
			line = line[:len(line)-1]
		}
		inputLines = append(inputLines, line)
	}
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	countStr := fmt.Sprintf("%02d", WsCount)
	freezeStr := fmt.Sprintf("%02d", WsFreeze)
	fmt.Fprintln(os.Stdout, "READINGS: "+countStr+" BELOW ZERO: "+freezeStr)
}

func main() {
	MainPara()
}
